import assert from 'node:assert/strict';
import { Room } from '../server/room.js';
const room = new Room('TEST');
clearInterval(room.iv);
const messages = [];
const socket = () => ({ readyState: 1, send: raw => messages.push(JSON.parse(raw)), close() { this.closed = true; } });
try {
  const ws = socket(), host = room.join(ws, 'Host', '');
  room.start(host, Date.now());
  assert.equal(room.ph, 'lobby', 'solo multiplayer cannot start');
  room.msg(ws, { t: 'bot' });
  assert.equal(room.ps.size, 2);
  const bot = [...room.ps.values()].find(p => p.bot);
  assert.equal(bot.ready, true);
  const other = room.join(socket(), 'Guest', '');
  room.addBot(other);
  assert.equal(room.ps.size, 3, 'only host can add bots');
  room.remove(other);
  room.start(host, Date.now());
  assert.equal(room.ph, 'count');
  host.sh = bot.sh = 0;
  host.x = 450; host.y = 280; bot.x = 550; bot.y = 280;
  const t = Date.now();
  room.msg(ws, {t:'in',mx:1,my:0,f:true,a:0,d:0});
  room.sim(t+301, 1/30);
  assert.equal(host.x, 450, 'stale input stops movement');
  assert.ok(!room.bs.some(b => b.o === host.id), 'stale input stops firing');
  assert.ok(bot.in.f, 'bots target and fire at an opponent');
  room.msg(ws, {t:'in',mx:1,my:1,f:true,a:0,d:0});
  room.drop(ws);
  assert.equal(host.in.f, false);
  assert.equal(host.in.mx, 0);
  const restored = socket();
  assert.equal(room.join(restored, 'Host', host.tok), host, 'rejoin retains identity');
  assert.equal(host.in.f, false);
  const replacement = socket(); room.join(replacement, 'Host', host.tok);
  assert.ok(restored.closed, 'rejoin replaces old socket');
  room.drop(restored);
  assert.equal(host.ws, replacement, 'old close cannot drop replacement');
  room.drop(replacement);host.off=Date.now()-21000;
  assert.equal(room.join(socket(), 'Host', host.tok), 'Rejoin window expired');
  room.remove(host);
  assert.equal(room.ps.size, 0, 'bot-only rooms are cleaned up');
  console.log('PASS input timeout, disconnect, rejoin, practice bots, host permissions and cleanup');
} finally { room.destroy(); }
